package com.bank.risk.service;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.logging.Logger;

// Maintains the running median of a BigDecimal stream using two heaps.
public class RunningMedian {
    private static final Logger log = Logger.getLogger(RunningMedian.class.getName());

    // Smaller half: max-heap (largest of the small half on top).
    private final PriorityQueue<BigDecimal> maxHeap =
            new PriorityQueue<>(Comparator.reverseOrder());
    // Larger half: min-heap (smallest of the large half on top).
    private final PriorityQueue<BigDecimal> minHeap = new PriorityQueue<>();

    public void addAmount(BigDecimal num) {
        if (maxHeap.isEmpty() || num.compareTo(maxHeap.peek()) <= 0) {
            maxHeap.offer(num);
        } else {
            minHeap.offer(num);
        }
        // Rebalance so sizes differ by at most one.
        if (maxHeap.size() > minHeap.size() + 1) {
            minHeap.offer(maxHeap.poll());
        } else if (minHeap.size() > maxHeap.size()) {
            maxHeap.offer(minHeap.poll());
        }
        log.fine(() -> "Added " + num + " | small=" + maxHeap.size()
                + " large=" + minHeap.size());
    }

    public BigDecimal median() {
        if (maxHeap.isEmpty()) {
            throw new IllegalStateException("No amounts in stream yet");
        }
        if (maxHeap.size() == minHeap.size()) {
            // Average of the two tops with controlled scale and rounding.
            return maxHeap.peek().add(minHeap.peek())
                    .divide(new BigDecimal("2"), 2, RoundingMode.HALF_UP);
        }
        return maxHeap.peek(); // odd count: max-heap holds the extra element
    }
}
