package com.bank.risk;

import com.bank.risk.service.RunningMedian;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class MedianApplication {
    private static final Logger log = Logger.getLogger(MedianApplication.class.getName());

    public static void main(String[] args) {
        RunningMedian rm = new RunningMedian();
        // Stream of National Bank of India transaction amounts.
        List<String> stream = List.of("500", "1500", "1000", "3000", "250");
        for (String s : stream) {
            BigDecimal amt = new BigDecimal(s);
            rm.addAmount(amt);
            log.info("After " + amt + " running median = " + rm.median());
        }
    }
}
